export type AlertProps =
  | { variant: 'success'; message: string }
  | { variant: 'error'; message: string; retry: () => void };

export function Alert(props: AlertProps) {
  return (
    <div role="alert">
      {props.message}
      {props.variant === 'error' ? (
        <button onClick={props.retry}>Retry</button>
      ) : null}
    </div>
  );
}
